1	"use client";
2	
3	import { Button } from "@repo/design-system/components/ui/button";
4	import { AnimatePresence, motion } from "motion/react";
5	import { createParser, parseAsStringLiteral, useQueryState } from "nuqs";
6	import { useEffect } from "react";
7	import { Era1Playground } from "./demos/era1-playground";
8	import { Era2Companion } from "./demos/era2-companion";
9	import { Era2Extraction } from "./demos/era2-companion/extraction-demo";
10	import { Era3Harness } from "./demos/era3-harness";
11	import { Era3Ladder } from "./demos/era3-ladder";
12	import { Era3Loop } from "./demos/era3-loop";
13	import { Era3Meter } from "./demos/era3-meter";
14	import { Era3Pipeline } from "./demos/era3-pipeline";
15	import { Era3Reach } from "./demos/era3-reach";
16	import { Era4Runtime } from "./demos/era4-runtime";
17	import { BeatFooter } from "./beat-footer";
18	import { BeatSlot } from "./beat-slot";
19	import { adjacentBeat, BEATS } from "./beats";
20	import { EraPanel } from "./era-panel";
21	import { FieldNote } from "./field-note";
22	import { Intro } from "./intro";
23	import {
24	  isArrowConsumingTarget,
25	  isPresenterToggle,
26	  isTextEntryTarget,
27	  stepKeyDirection,
28	} from "./step-keys";
29	import { StepperHeader } from "./stepper-header";
30	import { getAdjacentStep, STEPS, type StepId } from "./steps";
31	import { Synthesis } from "./synthesis";
32	import { useBeats } from "./use-beats";
33	
34	/** The four failures the reach demo walks one at a time. */
35	const REACH_BEATS = ["skipped", "bent", "left", "reached"] as const;
36	
37	const STEP_IDS = STEPS.map((s) => s.id);
38	
39	/**
40	 * The spec documents the entry URL as `?presenter=1` in bold, and `Shift+P`
41	 * must round-trip back to that same URL. `parseAsBoolean` only accepts the
42	 * literal string `"true"`, so both would silently fall through to the
43	 * default. This accepts `1`, `true` (any case) and the bare `?presenter`
44	 * flag (an empty value), and always serializes back to `"1"`.
45	 */
46	const parseAsPresenterFlag = createParser<boolean>({
47	  parse: (value) => {
48	    const normalized = value.toLowerCase();
49	    return normalized === "1" || normalized === "true" || normalized === "";
50	  },
51	  serialize: (value) => (value ? "1" : "false"),
52	});
53	
54	export function Masterclass() {
55	  const [step, setStep] = useQueryState(
56	    "step",
57	    parseAsStringLiteral(STEP_IDS as StepId[])
58	      .withDefault("intro")
59	      .withOptions({ history: "push" })
60	  );
61	
62	  const prev = getAdjacentStep(step, "prev");
63	  const next = getAdjacentStep(step, "next");
64	
65	  const [presenter, setPresenter] = useQueryState(
66	    "presenter",
67	    parseAsPresenterFlag.withDefault(false).withOptions({ history: "replace" })
68	  );
69	
70	  const { current: beat, go: goBeat, has } = useBeats(step, presenter);
71	
72	  useEffect(() => {
73	    const onKeyDown = (event: KeyboardEvent) => {
74	      if (isPresenterToggle(event) && !isTextEntryTarget(event.target)) {
75	        event.preventDefault();
76	        setPresenter(!presenter);
77	        return;
78	      }
79	      const dir = stepKeyDirection(event);
80	      if (!dir || isArrowConsumingTarget(event.target)) {
81	        return;
82	      }
83	      // One key for the whole talk: exhaust this step's beats, then move on.
84	      if (presenter) {
85	        const nextBeat = adjacentBeat(step, beat, dir);
86	        if (nextBeat) {
87	          goBeat(nextBeat);
88	          return;
89	        }
90	      }
91	      const adjacent = getAdjacentStep(step, dir);
92	      if (adjacent) {
93	        setStep(adjacent);
94	      }
95	    };
96	    window.addEventListener("keydown", onKeyDown);
97	    return () => window.removeEventListener("keydown", onKeyDown);
98	  }, [presenter, setPresenter, step, setStep, beat, goBeat]);
99	
100	  const reachRevealed = presenter
101	    ? REACH_BEATS.filter((id) => has(id)).length
102	    : undefined;
103	  const reachFenced = presenter ? has("fenced") : undefined;
104	
105	  return (
106	    <div className="flex min-h-dvh flex-col">
107	      <StepperHeader current={step} onSelect={setStep} />
108	      <main className="mx-auto w-full max-w-5xl flex-1 px-4 py-12 sm:py-16">
109	        <AnimatePresence mode="wait">
110	          <motion.div
111	            animate={{ opacity: 1 }}
112	            exit={{ opacity: 0 }}
113	            initial={{ opacity: 0 }}
114	            key={step}
115	            transition={{ duration: 0.2 }}
116	          >
117	            {step === "intro" && (
118	              <Intro onBegin={() => setStep("completion")} />
119	            )}
120	            {step === "completion" && (
121	              <EraPanel
122	                name="The completion machine"
123	                reality="Nobody was shipping software with this. But everything that came after is still this machine underneath: you feed it the start of a pattern and it continues — unaware of what you meant. Getting knowledge out took craft, until OpenAI taught it a format."
124	                years="2019–2022"
125	              >
126	                <Era1Playground presenter={presenter} />
127	                <FieldNote date="2022" label="post-training">
128	                  Asked for the capital of France, a base model offers the
129	                  capital of Germany, as a question. OpenAI&apos;s own labelers
130	                  preferred post-trained answers roughly 85% of the time over
131	                  the base model&apos;s; ChatGPT shipped on that flip nine
132	                  months later.
133	                </FieldNote>
134	              </EraPanel>
135	            )}
136	            {step === "integration" && (
137	              <EraPanel
138	                deepCut={
139	                  <p>
140	                    The speed was real, and so was the ceiling: the model saw
141	                    one file, one selection. Cursor had to fork VS Code to raise
142	                    it — the extension API allows a sidebar, not an editor that
143	                    thinks; indexing a codebase and editing across files needs
144	                    the core. That&apos;s why Copilot rode along as a plugin
145	                    while Cursor rebuilt the vehicle. The ceiling finally
146	                    cracked late in 2024, when models learned to reason —
147	                    multi-step thinking, the ingredient agents were waiting for.
148	                  </p>
149	                }
150	                expandLabel="Did you know? You were the bus."
151	                name="Extraction → Integration"
152	                reality="It answers now — in a browser tab, a world away from your code. You ferry context in and answers out by hand, until the chat moves into the editor and your selection becomes its context. Either way the verdict held: a senior engineer was faster. The model missed the file next door and the framework's basics, and correcting it cost more than writing it."
153	                years="2022–2024"
154	              >
155	                <BeatSlot show={has("tab")}>
156	                  <Era2Extraction />
157	                </BeatSlot>
158	                <BeatSlot show={has("editor")}>
159	                  <p className="mb-4 max-w-2xl text-muted-foreground text-sm">
160	                    Then the chat moved into the editor, and your selection
161	                    became its context — no more ferrying. This is the Cursor
162	                    moment. Watch what it still couldn&apos;t see:
163	                  </p>
164	                  <Era2Companion />
165	                </BeatSlot>
166	              </EraPanel>
167	            )}
168	            {step === "agentic-engineering" && (
169	              <EraPanel
170	                deepCut={
171	                  <p>
172	                    I didn&apos;t build the harness myself. The agent built its
173	                    own auditor; I set the rules it audits against. A page that
174	                    used to take hours of manual diffing came in at 2–3 hours of
175	                    the agent working a list I never had to touch — about a week
176	                    of work I didn&apos;t do.
177	                  </p>
178	                }
179	                expandLabel="Did you know? I didn't build the harness either."
180	                name="Agentic engineering"
181	                reality="Strip the debate away: an agent is an LLM with tools, trapped in a loop. Claude Code put that loop in a terminal — barely useful at first, even on the strongest coding models. Then the loop learned to run longer; minutes became hours. You stop writing syntax and start writing the rules the loop must satisfy."
182	                years="2024 → now"
183	              >
184	                <BeatSlot show={has("loop")}>
185	                  <Era3Loop />
186	                </BeatSlot>
187	                <BeatSlot show={has("reading")}>
188	                  <Era3Ladder />
189	                </BeatSlot>
190	                <BeatSlot show={has("run")}>
191	                  <Era3Reach fenced={reachFenced} revealed={reachRevealed} />
192	                </BeatSlot>
193	                <BeatSlot show={has("parity")}>
194	                  <p className="mt-10 mb-4 max-w-2xl text-muted-foreground text-sm">
195	                    I don&apos;t write Playwright. I can say what pixel for
196	                    pixel means, and I can tell when the answer is wrong. The
197	                    agent wrote the measuring tool; I wrote the rule it measures
198	                    against — a client&apos;s WordPress site, rebuilt in
199	                    Next.js:
200	                  </p>
201	                  <Era3Harness />
202	                </BeatSlot>
203	                <BeatSlot show={has("lanes")}>
204	                  <Era3Pipeline />
205	                </BeatSlot>
206	                <BeatSlot show={has("meter")}>
207	                  <Era3Meter />
208	                </BeatSlot>
209	              </EraPanel>
210	            )}
211	            {step === "outlook" && (
212	              <EraPanel
213	                deepCut={
214	                  <p>
215	                    The dashboard you just watched assemble is json-render under
216	                    the hood — a spec the model emits and the page compiles at
217	                    runtime. The same engine lets an end user build their own UI
218	                    without a developer in the loop. Code stops being a
219	                    permanent artifact and becomes a byproduct of intent.
220	                  </p>
221	                }
222	                expandLabel="Did you know? That dashboard didn't exist a second ago."
223	                name="The runtime frontier"
224	                reality="An honest label: this isn't lived experience yet — nobody works here daily. It's the model crossing out of the build phase into the running software itself: ask a question, and the interface is compiled on the spot. Try it on the questions that matter — the data behind it is real, German, and cited."
225	                years="2026 →"
226	              >
227	                <Era4Runtime />
228	              </EraPanel>
229	            )}
230	            {step === "synthesis" && <Synthesis />}
231	          </motion.div>
232	        </AnimatePresence>
233	      </main>
234	      {step !== "intro" && (
235	        <footer className="mx-auto flex w-full max-w-5xl items-center justify-between px-4 py-8">
236	          <Button
237	            disabled={!prev}
238	            onClick={() => prev && setStep(prev)}
239	            type="button"
240	            variant="ghost"
241	          >
242	            ← Back
243	          </Button>
244	          <Button
245	            disabled={!next}
246	            onClick={() => next && setStep(next)}
247	            type="button"
248	          >
249	            Next →
250	          </Button>
251	        </footer>
252	      )}
253	      {presenter && BEATS[step].length > 0 && (
254	        <>
255	          {/* Reserves the height the fixed transport takes out of the viewport. */}
256	          <div className="h-[4.5rem]" />
257	          <BeatFooter current={beat} onSelect={goBeat} step={step} />
258	        </>
259	      )}
260	    </div>
261	  );
262	}
