68	            <p className="font-mono text-[11px] text-muted-foreground tabular-nums">
69	              {stage.approx ? "~" : ""}
70	              {stage.lines} lines read
71	            </p>
72	          </div>
73	
74	          {/* The argument, as a measurement: what a human has to read collapses
75	              from a wall of diff to three sentences. */}
76	          <div className="mt-3 px-4">
77	            <div className="h-1 w-full overflow-hidden rounded-full bg-foreground/10">
78	              <div
79	                className="h-full min-w-[3px] rounded-full bg-ht-cyan-500 transition-[width] duration-500"
80	                style={{ width: `${(stage.lines / MAX_LINES) * 100}%` }}
81	              />
82	            </div>
83	          </div>
84	
85	          <div className="px-4 py-4">
86	            {/* `whitespace-pre` below is load-bearing: these are divs, so
87	                without it HTML collapses the diff's leading indentation and
88	                every nested line lands flush against the +. */}
89	            {stage.artifact === "diff" && (
90	              <div className="max-h-44 overflow-auto font-mono text-xs leading-5">
91	                {stage.body.map((l, i) => (
92	                  <div
93	                    className={cn("whitespace-pre", diffTone(l))}
94	                    key={`${i}-${l}`}
95	                  >
96	                    {l}
97	                  </div>
98	                ))}
99	              </div>
100	            )}
101	            {stage.artifact === "plan" && (
102	              <ol className="list-decimal space-y-1 pl-5 font-mono text-xs leading-6">
103	                {stage.body.map((l) => (
104	                  <li key={l}>{l.replace(/^\d+\.\s*/, "")}</li>
105	                ))}
106	              </ol>
107	            )}
108	            {stage.artifact === "design" && (
109	              <div className="grid gap-4 sm:grid-cols-2">
110	                <p className="font-mono text-xs leading-6">
111	                  {stage.body.join(" ")}
112	                </p>
113	                <TestRunner key={year} />
114	              </div>
115	            )}
116	          </div>
117	
118	          <p className="border-foreground/10 border-t px-4 py-3 text-foreground/55 text-sm italic">
119	            {stage.line}
120	          </p>
121	        </div>
122	      </div>
123	    </div>
124	  );
125	}
126	
127	function TestRunner() {
128	  const [passed, setPassed] = useState(0);
129	
130	  useEffect(() => {
131	    const reduce = window.matchMedia(
132	      "(prefers-reduced-motion: reduce)"
133	    ).matches;
134	    if (reduce) {
135	      setPassed(RUNNER_TESTS.length);
136	      return;
137	    }
138	    const id = setInterval(() => {
139	      setPassed((p) => Math.min(p + 1, RUNNER_TESTS.length));
140	    }, RUNNER_MS);
141	    return () => clearInterval(id);
142	  }, []);
143	
144	  return (
145	    <div className="rounded-md bg-[#0d1117] p-3 font-mono text-xs leading-6">
146	      {RUNNER_TESTS.map((t, i) => (
147	        <div
148	          className={i < passed ? "text-[#3fb950]" : "text-[#e5707e]"}
149	          key={t}
150	        >
151	          {i < passed ? "✓" : "✗"} {t}
152	        </div>
153	      ))}
154	      <div className="mt-1 text-[#8b949e]">
155	        {passed === RUNNER_TESTS.length
156	          ? `${RUNNER_TESTS.length} passed — nobody read the code.`
157	          : "running…"}
158	      </div>
159	    </div>
160	  );
161	}

