1	export type LaneId = "rag" | "wp" | "deps";
2	
3	export type LanePhase =
4	  | "plan"
5	  | "execute"
6	  | "validate"
7	  | "awaiting-signature"
8	  | "done";
9	
10	export interface LaneState {
11	  phase: LanePhase;
12	  ticksInPhase: number;
13	}
14	
15	export interface BoardState {
16	  lanes: Record<LaneId, LaneState>;
17	}
18	
19	export type BoardAction =
20	  | { type: "tick" }
21	  | { type: "handOff" }
22	  | { type: "approveMerge" }
23	  | { type: "fastForward" }
24	  | { type: "reset" };
25	
26	export const EXECUTE_TICKS = 4;
27	export const VALIDATE_TICKS = 2;
28	
29	const LANE_IDS: readonly LaneId[] = ["rag", "wp", "deps"];
30	
31	export function initialBoardState(): BoardState {
32	  return {
33	    lanes: {
34	      deps: { phase: "execute", ticksInPhase: 0 },
35	      rag: { phase: "plan", ticksInPhase: 0 },
36	      wp: { phase: "execute", ticksInPhase: 0 },
37	    },
38	  };
39	}
40	
41	function tickLane(id: LaneId, lane: LaneState): LaneState {
42	  if (
43	    lane.phase === "plan" ||
44	    lane.phase === "awaiting-signature" ||
45	    lane.phase === "done"
46	  ) {
47	    return lane;
48	  }
49	  const ticks = lane.ticksInPhase + 1;
50	  if (lane.phase === "execute") {
51	    return ticks >= EXECUTE_TICKS
52	      ? { phase: "validate", ticksInPhase: 0 }
53	      : { phase: "execute", ticksInPhase: ticks };
54	  }
55	  // validate
56	  if (ticks >= VALIDATE_TICKS) {
57	    return id === "deps"
58	      ? { phase: "awaiting-signature", ticksInPhase: 0 }
59	      : { phase: "done", ticksInPhase: 0 };
60	  }
61	  return { phase: "validate", ticksInPhase: ticks };
62	}
63	
64	function tickBoard(state: BoardState): BoardState {
65	  return {
66	    lanes: {
67	      deps: tickLane("deps", state.lanes.deps),
68	      rag: tickLane("rag", state.lanes.rag),
69	      wp: tickLane("wp", state.lanes.wp),
70	    },
71	  };
72	}
73	
74	export function isSettled(state: BoardState): boolean {
75	  return LANE_IDS.every((id) => {
76	    const { phase } = state.lanes[id];
77	    return (
78	      phase === "plan" || phase === "awaiting-signature" || phase === "done"
79	    );
80	  });
81	}
82	
83	export function isBoardDone(state: BoardState): boolean {
