      </div>
    );
  }
  if (phase === "validating") {
    return (
      <div className={cn(CELL, "border-ht-cyan-500/50")}>
        <button
          className={ACTION}
          onClick={() => dispatch({ lane: laneId, type: "accept" })}
          type="button"
        >
          Accept ✓
        </button>
      </div>
    );
  }
  if (phase === "validated") {
    return (
      <div className={cn(CELL, "border-foreground/10")}>
